/* Rate-Daten (Hinweise & Merkmale) */
window.GG_DATA=[{"id":"tiere","name":"Tiere","icon":"🐾","qs":[{"k":"saeuger","t":"Ist es ein Säugetier?"},{"k":"fliegt","t":"Kann es fliegen?"},{"k":"wasser","t":"Lebt es hauptsächlich im Wasser?"},{"k":"fleisch","t":"Frisst es hauptsächlich Fleisch?"},{"k":"fell","t":"Hat es Fell?"},{"k":"europa","t":"Lebt es in Europa in freier Wildbahn?"},{"k":"gross","t":"Ist es größer als ein Hund?"},{"k":"beine","t":"Hat es mehr als vier Beine?"},{"k":"haus","t":"Wird es als Haus- oder Nutztier gehalten?"},{"k":"eier","t":"Legt es Eier?"},{"k":"gefahr","t":"Kann es Menschen gefährlich werden?"},{"k":"streifen","t":"Hat es auffällige Streifen oder Flecken?"},{"k":"nacht","t":"Ist es überwiegend nachtaktiv?"}],"items":[{"a":"Elefant","c":["Seine Tragzeit dauert etwa 22 Monate","Ist das schwerste an Land lebende Tier","Hat riesige Fächerohren und Stoßzähne aus Elfenbein","Trinkt und greift mit einer muskulösen, bis zum Boden reichenden Nase","Graues Riesentier mit Rüssel und Stoßzähnen aus Afrika und Asien"],"alt":["afrikanischer elefant"],"at":"1000001000100"},{"a":"Delfin","c":["Schläft nur mit einer Gehirnhälfte, die andere bleibt wach","Orientiert sich unter Wasser mit Ultraschall-Klicklauten","Atmet über ein Blasloch am Kopf Luft","Gilt als sehr intelligentes, verspieltes Meeressäugetier","Hat Schnauze und Rückenflosse und springt gern aus dem Wasser"],"alt":["delphin"],"at":"1011011000000"},{"a":"Biene","c":["Verständigt sich über einen Schwänzeltanz","Ein Volk zählt im Sommer bis zu rund 50.000 Tiere um eine Königin","Baut Waben aus Wachs","Sammelt Nektar und Pollen, bestäubt Blüten und erzeugt Honig","Gelb-schwarz gestreiftes Insekt mit Stachel, das in Stöcken Honig produziert"],"alt":["honigbiene"],"at":"0100010111110"},{"a":"Giraffe","c":["Ihre dunkle Zunge ist etwa 45 cm lang","Hat im Hals genau sieben Wirbel, wie die meisten Säugetiere","Neugeborene fallen aus fast zwei Metern Höhe zu Boden","Lebt in der Savanne Afrikas und frisst Akazienblätter","Höchstes Landtier der Welt mit extrem langem Hals und gefleckter Haut"],"at":"1000101000010"},{"a":"Seestern","c":["Besitzt kein Gehirn","Kann verlorene Körperteile wieder nachwachsen lassen","Bewegt sich auf Hunderten winziger Saugfüßchen","Lebt am Meeresboden und stülpt zum Verdauen von Muscheln den Magen aus","Meerestier mit meist fünf Armen, die strahlenförmig vom Körper abgehen"],"at":"0011010001000"},{"a":"Adler","c":["Sein Sehvermögen ist ein Mehrfaches schärfer als das des Menschen","Baut riesige Nester, sogenannte Horste, auf Felsen oder hohen Bäumen","Hat einen kräftigen Hakenschnabel und scharfe Krallen","Kreist mit weit gespannten Flügeln in der Luft","Großer Greifvogel, der im deutschen Bundeswappen abgebildet ist"],"at":"0101010001000"},{"a":"Zebra","c":["Kein Tier gleicht dem anderen im Muster, wie bei einem Fingerabdruck","Lebt in Herden in den Savannen Afrikas","Wird anders als nahe Verwandte kaum je als Reittier gehalten","Gehört zur Familie der Pferde","Pferdeartiges Tier mit schwarz-weißem Streifenmuster"],"at":"1000101000010"},{"a":"Fledermaus","c":["Ihre Flügel bestehen aus Haut, die zwischen extrem langen Fingern gespannt ist","Hängt zum Schlafen kopfüber, oft in Höhlen oder auf Dachböden","Findet im Dunkeln Beute mithilfe von Ultraschall-Rufen","Einziges Säugetier, das aktiv fliegen kann","Nachtaktives Flugsäugetier, das Insekten jagt und tagsüber kopfüber hängt"],"at":"1101110000001"},{"a":"Pferd","c":["Kann im Stehen schlafen, weil Sehnen und Bänder die Beine stabilisieren","Das Männchen heißt Hengst, das Weibchen Stute, sie werden auch im Turnier geritten","Rassen reichen vom Shetlandpony bis zum schweren Kaltblut","Wird seit Jahrtausenden geritten und vor Kutschen gespannt","Huftier mit Mähne, das als Reittier gehalten wird; das Junge heißt Fohlen"],"at":"1000101010000"},{"a":"Kobra","c":["Gehört zu den Giftnattern","Ihr Gift wirkt vor allem auf das Nervensystem","Lebt in Afrika und Asien und wird oft von Schlangenbeschwörern gezeigt","Spreizt bei Bedrohung die Halsrippen zu einem Schild","Giftschlange, die ihren Hals zu einer Haube aufstellt"],"alt":["brillenschlange"],"at":"0001000001100"},{"a":"Clownfisch","c":["Alle Jungtiere sind zunächst männlich, später wird eines weiblich","Ist durch Schleim gegen das Nesselgift seiner Wirtstiere geschützt","Lebt geschützt zwischen den Tentakeln einer Seeanemone","Orange mit weißen Streifen, lebt in tropischen Korallenriffen","Orange-weißer Meeresbewohner, bekannt aus einem Animationsfilm über Nemo"],"alt":["anemonenfisch","nemo"],"at":"0010000001010"},{"a":"Eisbär","c":["Unter seinem Fell ist die Haut schwarz","Sein Fell wirkt weiß, die Haare sind aber durchsichtig und hohl","Kann viele Kilometer weit im Meer schwimmen","Jagt vor allem Robben am Rand des Packeises","Größtes an Land lebendes Raubtier der Arktis mit weißem Fell"],"alt":["polarbär"],"at":"1001111000100"},{"a":"Igel","c":["Ein erwachsenes Tier trägt mehrere Tausend Stacheln","Hält in Mitteleuropa im Winter Winterschlaf","Ernährt sich vor allem von Insekten, Schnecken und Würmern","Rollt sich bei Gefahr zu einer Kugel zusammen","Kleines nachtaktives Säugetier mit Stachelkleid, oft in Gärten"],"at":"1001010000001"},{"a":"Libelle","c":["Ihre Larven leben mehrere Monate bis Jahre unter Wasser","Kann die Flügelpaare unabhängig bewegen und in der Luft stehen","Hat riesige Facettenaugen, die fast den ganzen Kopf einnehmen","Jagt im Flug andere Insekten und lebt oft nahe Teichen","Schlankes Insekt mit vier durchsichtigen Flügeln und langem Hinterleib"],"at":"0101010101000"},{"a":"Marienkäfer","c":["Verteidigt sich mit einer bitter schmeckenden Flüssigkeit aus den Beingelenken","Seine Larven fressen ebenfalls viele Blattläuse","Unter den Flügeldecken liegen zusammengefaltete Flügel","Vertilgt Blattläuse und gilt als Glücksbringer","Kleines rotes Insekt mit schwarzen Punkten"],"alt":["glückskäfer"],"at":"0101010101010"},{"a":"Wolf","c":["Ein Rudel besteht meist aus einem Elternpaar und dessen Nachwuchs","Verständigt sich über Körpersprache und weithin hörbares Heulen","Wurde in Deutschland ausgerottet und ist seit etwa dem Jahr 2000 zurück","Ist der wilde Vorfahr des Haushundes","Grauer Verwandter des Hundes, der im Rudel jagt und heult"],"at":"1001111000101"},{"a":"Känguru","c":["Das Neugeborene ist nur etwa zwei Zentimeter groß","Sein kräftiger Schwanz dient als Stütze und Gleichgewichtshilfe","Bewegt sich hüpfend auf kräftigen Hinterbeinen fort","Trägt den Nachwuchs im Beutel am Bauch","Australisches Beuteltier, das hüpfend flüchtet"],"at":"1000101000000"},{"a":"Nashorn","c":["Sein Horn besteht aus Keratin, dem Stoff unserer Fingernägel","Sieht schlecht, hat aber einen sehr guten Geruchssinn","Läuft trotz massigem Körper bis zu etwa 40 km/h schnell","Wird wegen seines Horns stark von Wilderern bedroht","Massiges Tier mit ein oder zwei Hörnern auf der Nase"],"alt":["rhinozeros"],"at":"1000001000100"},{"a":"Eichhörnchen","c":["Vergisst viele seiner angelegten Nahrungsverstecke wieder","Seine Nagezähne wachsen lebenslang nach","Klettert geschickt und balanciert mit dem buschigen Schwanz","Vergräbt im Herbst Nüsse und Samen als Wintervorrat","Kleines rotbraunes Nagetier mit buschigem Schwanz, das auf Bäumen lebt"],"alt":["eichhorn"],"at":"1000110000000"},{"a":"Piranha","c":["Hat dreieckige, scharfkantige Zähne","Wird in Filmen oft gefährlicher dargestellt, als er wirklich ist","Lebt in Flüssen Südamerikas, etwa im Amazonasgebiet","Gilt als blutrünstiger Raubfisch, der im Schwarm jagt","Süßwasserfisch mit messerscharfen Zähnen aus dem Amazonas"],"at":"0011000001000"},{"a":"Forelle","c":["Braucht kaltes, sauerstoffreiches Wasser","Wird häufig in Zuchtteichen aufgezogen","Schwimmt gegen die Strömung in klaren Gebirgsbächen","Hat auf der Haut dunkle oder rote Tupfen","Gefleckter Süßwasserfisch klarer Bäche, den man gern angelt und gebraten isst"],"alt":["bachforelle"],"at":"0011010001010"},{"a":"Komodowaran","c":["Sein Speichel enthält Bakterien und Gift, das Beute schwächt","Nimmt Aas über mehrere Kilometer Entfernung wahr","Lebt nur auf wenigen indonesischen Inseln","Mit bis zu drei Metern Länge die größte lebende Echse","Riesige Echse aus Indonesien, auch Drache genannt"],"alt":["komodo waran","komododrache"],"at":"0001001001100"},{"a":"Dromedar","c":["Kann in kurzer Zeit über 100 Liter Wasser trinken","Seine Höcker speichern Fett, kein Wasser","Hat dichte Wimpern und verschließbare Nasenlöcher gegen Sand","Gilt als Schiff der Wüste","Einhöckriges Wüstentier, das als Reit- und Lasttier genutzt wird"],"alt":["kamel","einhöckriges kamel"],"at":"1000101010000"},{"a":"Elch","c":["Sein Schaufelgeweih kann über zwei Meter breit werden","Schwimmt gut und taucht sogar nach Wasserpflanzen","Kann über 500 Kilogramm schwer werden","Ist die größte lebende Hirschart","Riesiger Hirsch Skandinaviens und Kanadas mit Schaufelgeweih"],"at":"1000111000100"},{"a":"Esel","c":["Hat ein ausgezeichnetes Gedächtnis und gilt als trittsicher","Stammt von wilden Verwandten aus Nordostafrika ab","Gibt Laute von sich, die als I-Aah beschrieben werden","Ist kleiner als ein Pferd und hat längere Ohren","Grautier mit langen Ohren, das Lasten trägt"],"at":"1000101010000"},{"a":"Uhu","c":["Sein Flug ist fast lautlos wegen weicher Federränder","Kann den Kopf um etwa 270 Grad drehen","Hat große orange Augen und Federbüschel, die wie Ohren aussehen","Größte Eule Europas","Großer nachtaktiver Vogel mit orangen Augen, Federohren und tiefem Ruf"],"at":"0101010001001"},{"a":"Gorilla","c":["Männchen entwickeln im Alter einen silbrig gefärbten Rücken","Baut jeden Abend ein neues Nest zum Schlafen","Lebt in Familiengruppen in den Regenwäldern Zentralafrikas","Größte lebende Primatenart","Menschenaffe, der sich zum Drohen auf die Brust trommelt"],"at":"1000101000100"},{"a":"Riesenschildkröte","c":["Kann über 150 Jahre alt werden","Wiegt oft mehr als 200 Kilogramm","Lebt vor allem auf den Galapagosinseln und den Seychellen","Trägt einen Panzer, in den sie Kopf und Beine einziehen kann","Langlebiges Reptil mit Panzer, das sehr langsam geht"],"alt":["galapagosschildkröte","galapagos-riesenschildkröte"],"at":"0000001001000"},{"a":"Hirsch","c":["Sein Geweih wächst im Frühjahr in wenigen Monaten komplett nach","Die Männchen kämpfen im Herbst um die Weibchen und röhren dabei","Das Junge trägt ein geflecktes Fell und heißt Kalb","Wiederkäuer, der in Wäldern lebt und Gras, Knospen und Rinde frisst","Waldbewohner mit verzweigtem Geweih, der bei der Brunft röhrt"],"alt":["rothirsch"],"at":"1000111000000"},{"a":"Kuh","c":["Hat einen Magen mit vier Abschnitten","Kaut ihr Futter ein zweites Mal wieder","Eine Milchrasse gibt am Tag oft über 20 Liter Milch","Trägt auf der Alm oft eine Glocke und grast auf der Weide","Nutztier, das Milch und Rindfleisch liefert und muht"],"alt":["rind","hausrind"],"at":"1000101010000"}]},{"id":"berufe","name":"Berufe","icon":"👷","qs":[{"k":"draussen","t":"Arbeitet man überwiegend draußen?"},{"k":"studium","t":"Braucht man meist ein Studium?"},{"k":"tiere","t":"Arbeitet man mit Tieren?"},{"k":"computer","t":"Arbeitet man hauptsächlich am Computer?"},{"k":"uniform","t":"Trägt man Dienstkleidung oder Uniform?"},{"k":"schicht","t":"Arbeitet man oft im Schichtdienst?"},{"k":"handwerk","t":"Arbeitet man handwerklich mit den Händen?"},{"k":"helfen","t":"Hilft man Menschen direkt (Gesundheit, Sicherheit, Betreuung)?"},{"k":"abends","t":"Arbeitet man oft abends oder nachts?"},{"k":"gesund","t":"Ist es ein Beruf im Gesundheitswesen?"},{"k":"kunden","t":"Hat man viel direkten Kundenkontakt?"},{"k":"fahrzeug","t":"Fährt oder steuert man Fahrzeuge?"},{"k":"kreativ","t":"Ist es ein kreativer oder künstlerischer Beruf?"}],"items":[{"a":"Bäcker","c":["Der Arbeitstag beginnt oft mitten in der Nacht","Mehl gehört zum täglichen Material","Hier entstehen Brötchen, Brezeln und Torten","Teig wird geknetet, geformt und im heißen Ofen gegart","Frühmorgens duftet es in der Filiale nach frischem Brot und Brötchen"],"alt":["bäckerin"],"at":"0000001010100"},{"a":"Pilot","c":["Der Arbeitsplatz befindet sich oft in mehreren Tausend Metern Höhe","Die Arbeit führt regelmäßig über Zeitzonen hinweg","Vor dem Einsatz werden Wetter, Route und Kraftstoffmenge geprüft","Er sitzt im Cockpit und spricht mit dem Tower","Er steuert ein Verkehrsflugzeug und begrüßt die Passagiere per Durchsage"],"alt":["pilotin","flugzeugführer"],"at":"0000110010010"},{"a":"Krankenpfleger","c":["Der Dienst ist in Früh-, Spät- und Nachtschicht eingeteilt","Zum Alltag gehören Blutdruckmessen und das Verteilen von Medikamenten","Sein Arbeitsort ist meist eine Station in der Klinik","Er wechselt Verbände, misst Fieber und hilft beim Waschen","Er versorgt Patienten in der Klinik und arbeitet eng mit Ärzten zusammen"],"alt":["krankenschwester","krankenpflegerin","pfleger"],"at":"0000110111000"},{"a":"Förster","c":["Der Arbeitsplatz hat keine Wände und keine Bürotür","Seine Aufgabe ist der Schutz und die Pflege eines großen Naturgebiets","Er plant, wo Bäume gepflanzt oder gefällt werden","Er kennt Reh, Hirsch und Wildschwein in seinem Revier","Er betreut ein Waldrevier und achtet auf gesunde Bäume und Wildbestand"],"alt":["försterin"],"at":"1100000000000"},{"a":"Programmierer","c":["Ein Großteil des Tages verläuft im Sitzen vor dem Bildschirm","Fehler in der Arbeit heißen oft Bugs","Sprachen wie Python, Java oder C++ gehören zum Handwerkszeug","Er entwickelt Software und sucht Fehler im Quellcode","Er schreibt Code, aus dem Apps, Webseiten und Computerspiele entstehen"],"alt":["programmiererin","softwareentwickler","entwickler"],"at":"0101000000000"},{"a":"Friseur","c":["Der Beruf verlangt viel Gespräch und ein ruhiges Händchen","Kundinnen verlassen den Laden oft mit einem neuen Look","Zum Handwerkszeug gehören Schere, Kamm und Föhn","Er wäscht, schneidet und färbt Haare","Im Salon schneidet er Haare und legt Locken"],"alt":["friseurin","frisör"],"at":"0000001000101"},{"a":"Feuerwehrmann","c":["Alarm kann jederzeit den Dienst unterbrechen","Schlauch, Leiter und Atemschutz gehören zur Ausrüstung","Auf der Wache stehen Einsatzkleidung und Stiefel immer bereit","Er löscht Brände und befreit Menschen aus Unfallautos","Er rückt im roten Einsatzwagen aus, um Brände zu bekämpfen"],"alt":["feuerwehrfrau","feuerwehr"],"at":"0000110110010"},{"a":"Lehrer","c":["Zuhause warten oft noch Hefte, die durchgesehen werden müssen","Die Arbeitswoche folgt einem festen Stundenplan","Er bereitet Unterricht vor, korrigiert Klassenarbeiten und gibt Noten","Vor einer Tafel erklärt er Mathe, Deutsch oder Englisch","Er unterrichtet Schüler in einer Klasse"],"alt":["lehrerin"],"at":"0100000000000"},{"a":"Schauspieler","c":["Der Text muss auswendig sitzen","Proben, Castings und Applaus bestimmen den Alltag","Die Arbeit findet auf einer Bühne oder an einem Filmset statt","Er verkörpert Rollen und lernt dafür lange Texte","Er steht auf der Bühne oder vor der Kamera und stellt Figuren dar"],"alt":["schauspielerin"],"at":"0000000010001"},{"a":"Tierarzt","c":["Die Patienten können nicht sagen, wo es wehtut","Impfen, Operieren und Untersuchen gehören zum Alltag","Besitzer warten besorgt im Wartezimmer auf ihre Schützlinge","Zu den Patienten zählen Hunde, Katzen, Pferde und Kühe","Er behandelt Hund, Katze und Hamster in seiner Praxis oder auf dem Bauernhof"],"alt":["tierärztin","veterinär"],"at":"0110000000100"},{"a":"Busfahrer","c":["Der Arbeitstag folgt einem festen Takt aus Linien und Haltestellen","Sein Arbeitsplatz ist ein Sitz hinter einem sehr großen Lenkrad","Er verkauft Tickets und öffnet an Haltestellen die Türen","Er bringt Pendler und Schulkinder durch Stadt und Land","Er lenkt ein großes Gefährt mit vielen Sitzplätzen auf festen Linien im Nahverkehr"],"alt":["busfahrerin","buschauffeur"],"at":"0000110010110"},{"a":"Zahnarzt","c":["Viele Patienten haben vor dem Termin ein mulmiges Gefühl","Bohrer, Spiegel und Sonde liegen auf dem Instrumententisch","Die Patienten liegen auf einem Stuhl mit einer hellen Lampe darüber","Er bekämpft Karies und setzt Füllungen und Kronen","Er untersucht den Mund, entfernt Karies und setzt Füllungen"],"alt":["zahnärztin","dentist"],"at":"0100101101100"},{"a":"Dachdecker","c":["Schwindelfreiheit ist eine Grundvoraussetzung","Bei Regen und Sturm ruht die Arbeit meist","Ziegel, Schiefer und Bitumenbahnen sind das Material","Er arbeitet hoch oben auf Gerüsten und Leitern","Er verlegt Ziegel ganz oben auf Häusern, damit es nicht hineinregnet"],"alt":["dachdeckerin"],"at":"1000001000000"},{"a":"Koch","c":["Wenn andere zu Mittag und Abend essen, hat er Hochbetrieb","Messer, Pfannen und Töpfe sind sein Werkzeug","Er arbeitet in einer Küche mit Herd und Dunstabzug","Er trägt eine weiße Jacke und hohe Mütze und würzt Soßen ab","Er bereitet im Restaurant Menüs zu, die dann serviert werden"],"alt":["köchin","chefkoch"],"at":"0000111010001"},{"a":"Polizist","c":["Auch an Feiertagen und Wochenenden ist Dienst","Er hat Befugnisse, Menschen vorübergehend festzunehmen","Er nimmt Anzeigen auf und sichert Unfallstellen","Er geht mit Dienstwaffe und Funkgerät Streife","Er trägt eine Uniform, sorgt für Recht und Ordnung und jagt Verbrecher"],"alt":["polizistin","streifenpolizist"],"at":"0000110110010"},{"a":"Kellner","c":["Die Arbeit läuft vor allem, wenn andere frei haben","Ein Tablett gehört zum Standardzubehör","Er nimmt Bestellungen auf und notiert sie für die Küche","Er trägt Teller und Getränke an die Tische der Gäste","Er bedient im Restaurant die Gäste und bringt am Ende die Rechnung"],"alt":["kellnerin","bedienung"],"at":"0000010010100"},{"a":"Schäfer","c":["Sein wichtigster Mitarbeiter hat vier Pfoten und bellt","Er verbringt viel Zeit auf Weiden und Deichen","Er hütet eine Herde und führt sie von Weide zu Weide","Er schert Tiere, damit Wolle gewonnen wird","Er zieht mit einem Hirtenstab und seinem Hund hinter Wollvieh her"],"alt":["schäferin","hirte"],"at":"1010000000000"},{"a":"Architekt","c":["Am Anfang des Auftrags steht meist eine Skizze","Maßstab, Lineal und Grundriss gehören zum Fachvokabular","Er zeichnet Pläne am Rechner, bevor Bagger rollen","Er entwirft Gebäude und beachtet dabei Statik und Bauvorschriften","Er plant Häuser und Gebäude, bevor sie gebaut werden"],"alt":["architektin"],"at":"0101000000001"},{"a":"Taxifahrer","c":["Der Arbeitsplatz ist ein Auto mit einem leuchtenden Schild auf dem Dach","Er kennt die Stadt gut und nutzt trotzdem das Navi","Am Ende der Strecke wird nach dem Zähler abgerechnet","Er holt Menschen per Anruf oder App ab und bringt sie zum Ziel","Man winkt ihn an der Straße herbei, und er bringt einen gegen Geld ans Ziel"],"alt":["taxifahrerin","taxi"],"at":"0000010010110"},{"a":"Fotograf","c":["Das richtige Licht ist wichtiger als das Gerät","Blende, Belichtung und Brennweite sind tägliche Begriffe","Hochzeiten, Porträts und Reportagen sind typische Aufträge","Er hängt sich eine Kamera um und sucht Motive","Er hält Momente mit der Kamera fest und liefert Bilder an Kunden und Magazine"],"alt":["fotografin"],"at":"0000000000101"},{"a":"Landwirt","c":["Der Tag beginnt früh und endet erst, wenn die Arbeit getan ist","Das Wetter entscheidet über Erfolg oder Verlust der Ernte","Traktor und Mähdrescher sind wichtige Maschinen","Er bestellt Felder, erntet Getreide und füttert Kühe und Schweine","Er arbeitet auf einem Hof mit Äckern, Stall und Vieh und liefert Milch und Getreide"],"alt":["bauer","landwirtin","bäuerin"],"at":"1010001000010"},{"a":"Apotheker","c":["Er kennt Wirkstoffe und mögliche Wechselwirkungen genau","Rezepte werden hier geprüft und Packungen aus Schubladen gezogen","Er berät zu Medikamenten, Salben und Hustensaft","Er arbeitet in einem Laden, dessen Schild ein rotes A zeigt, und gibt Arzneien über den Tresen","Er gibt gegen Rezept Tabletten und Salben aus und berät dazu"],"alt":["apothekerin"],"at":"0100000101100"},{"a":"Metzger","c":["Der Arbeitstag beginnt oft früh und in kalten Räumen","Beil, scharfe Messer und eine Kühltheke gehören dazu","Er zerlegt Rind und Schwein in Teile wie Keule, Rücken und Filet","Er stellt Wurst und Schinken her","Hinter der Theke verkauft er Steaks, Schnitzel, Wurst und Schinken"],"alt":["fleischer","metzgerin","fleischerin"],"at":"0000001000100"},{"a":"Rettungssanitäter","c":["Der Dienst kann mitten in der Nacht beginnen und sofort in Hektik münden","Oft arbeitet er zu zweit und mit einem Notarzt zusammen","Sein Fahrzeug ist mit Trage, Defibrillator und Notfallkoffer ausgestattet","Er versorgt Verletzte am Unfallort und bringt sie ins Krankenhaus","Er fährt mit Blaulicht zu Notfällen und leistet Erste Hilfe im Krankenwagen"],"alt":["notfallsanitäter","sanitäter","rettungsassistent"],"at":"0000110111010"},{"a":"Schornsteinfeger","c":["Wer seinen Knopf berührt, soll Glück haben","Schwarze Kleidung und ein Zylinder sind sein Markenzeichen","Er prüft Heizungen und Abgasanlagen auf Sicherheit","Er klettert aufs Dach und kehrt Ruß aus Kaminen","Er kehrt Kamine und gilt als Glücksbringer"],"alt":["schornsteinfegerin","kaminkehrer"],"at":"0000101000100"},{"a":"Astronaut","c":["Vor dem Einsatz steht jahrelanges Training und strenge Auswahl","Bei der Arbeit herrscht Schwerelosigkeit","Der Arbeitsplatz kreist rund 400 Kilometer über der Erde","Er fliegt mit einer Rakete ins All und arbeitet auf der ISS","Er schwebt im Raumanzug durch eine Raumstation"],"alt":["astronautin","kosmonaut"],"at":"0100100000010"},{"a":"Richter","c":["Sein Wort am Ende einer Verhandlung hat bindende Wirkung","Im Saal trägt er eine schwarze Robe","Er hört Zeugen an und wägt Beweise ab","Er verkündet Urteile in Straf- und Zivilprozessen","Er leitet eine Verhandlung und fällt im Namen des Volkes das Urteil"],"alt":["richterin"],"at":"0100100000000"},{"a":"Verkäufer","c":["Er steht viele Stunden auf den Beinen","Sein Arbeitsplatz hat Regale, Kasse und viele Kunden","Er berät Kunden, füllt Regale auf und bedient die Kasse","Er arbeitet im Geschäft und berät Menschen bei der Auswahl von Waren","Er arbeitet im Laden und bedient Kunden an der Kasse"],"alt":["verkäuferin"],"at":"0000000000100"},{"a":"Bankkaufmann","c":["Vertrauen und Verschwiegenheit sind in diesem Beruf besonders wichtig","Zinsen, Kredite und Konten gehören zum Tagesgeschäft","Er berät zu Sparplänen, Krediten und Geldanlagen","Hinter dem Schalter zahlt er Geld aus und eröffnet Konten","Er berät Kunden in einer Sparkasse zu Konto, Kredit und Geldanlage"],"alt":["bankkauffrau","bankangestellter"],"at":"0001000000100"},{"a":"Bildhauer","c":["Das Ergebnis ist ein Kunstwerk, das man umrunden kann","Staub, Hammer und Meißel prägen den Arbeitsalltag","Sein Material ist oft Marmor, Sandstein oder Bronze","Er meißelt aus einem Block eine Figur","Er schafft Skulpturen und Statuen für Museen und Plätze"],"alt":["bildhauerin"],"at":"0000001000001"}]},{"id":"laender","name":"Länder","icon":"🌍","qs":[{"k":"europa","t":"Liegt es in Europa?"},{"k":"kueste","t":"Hat es Zugang zum Meer?"},{"k":"insel","t":"Ist es eine Insel oder ein Inselstaat?"},{"k":"deutsch","t":"Wird dort (auch) Deutsch als Amtssprache gesprochen?"},{"k":"gross","t":"Ist es größer als Deutschland?"},{"k":"asien","t":"Liegt es in Asien?"},{"k":"monarchie","t":"Ist es eine Monarchie?"},{"k":"warm","t":"Ist es überwiegend warm oder heiß?"},{"k":"berge","t":"Gibt es dort sehr hohe Gebirge (über 4000 m)?"},{"k":"sued","t":"Liegt es überwiegend auf der Südhalbkugel?"},{"k":"grenze","t":"Grenzt es direkt an Deutschland?"}],"items":[{"a":"Spanien","c":["Liegt im Südwesten Europas und teilt sich seine Halbinsel mit einem kleineren Nachbarn","Dort hält man Siesta und isst abends sehr spät","Stierkampf und Flamenco gelten als traditionelle Kulturgüter","Paella stammt aus Valencia, und die Sagrada Família steht in Barcelona","Hauptstadt ist Madrid; Sangria und Tapas sind weltbekannt"],"at":"11001011000"},{"a":"Island","c":["Liegt im Nordatlantik, knapp unterhalb des Polarkreises","Ein Land aus Feuer und Eis mit vielen Vulkanen und Gletschern","Geysire und heiße Quellen sind eine große Touristenattraktion","Hier driften die nordamerikanische und die eurasische Erdplatte auseinander","Reykjavik ist die nördlichste Hauptstadt eines souveränen Staates"],"at":"11100000000"},{"a":"Schweiz","c":["Kleiner Binnenstaat im Herzen Europas mit vier Landessprachen","Berühmt für Schokolade, Käse mit Löchern und präzise Uhren","Das Matterhorn und der Genfer See liegen dort","Die Hauptstadt heißt Bern, Zahlungsmittel ist der Franken","Neutrales Alpenland, in dem Zürich und Genf als Banken- und Weltstädte gelten"],"at":"10010000101"},{"a":"Frankreich","c":["Seine Umrisse werden oft mit einem Sechseck verglichen","Baguette, Käse und Wein gehören zur Esskultur","Der Eiffelturm und der Louvre stehen in seiner Hauptstadt","Hier endet die Tour de France traditionell auf den Champs-Élysées","Westlicher Nachbar Deutschlands mit Paris als Hauptstadt"],"at":"11001000101"},{"a":"Schweden","c":["Liegt im Norden Europas auf der skandinavischen Halbinsel","Dort gibt es die Kaffeepause Fika mit Zimtschnecke und das Jedermannsrecht in der Natur","Pippi Langstrumpf und ein blau-gelbes Möbelhaus stammen von dort","Der Stifter des Nobelpreises kam aus diesem Land","Hauptstadt Stockholm; die Flagge ist blau mit gelbem Kreuz"],"at":"11001010000"},{"a":"Griechenland","c":["Liegt am Mittelmeer im Südosten Europas","Tausende Inseln, darunter Kreta und Rhodos, gehören dazu","Wiege der Demokratie und der Olympischen Spiele","Die Akropolis ist das bekannteste Bauwerk der Antike dort","Gyros, Feta und Ouzo; Hauptstadt ist Athen"],"at":"11000001000"},{"a":"Polen","c":["Liegt östlich von Deutschland und grenzt im Norden an die Ostsee","Kopernikus, der das Sonnensystem neu beschrieb, wurde dort geboren","Pierogi und Wodka sind bekannte kulinarische Exporte","Die Weichsel fließt durch die Hauptstadt Warschau","Östlicher Nachbar Deutschlands mit den Städten Krakau und Danzig"],"at":"11000000001"},{"a":"Belgien","c":["Westeuropäischer Staat mit den Regionen Flandern und Wallonien","Waffeln, Pralinen und Pommes frites gelten als Spezialitäten","In der Hauptstadt sitzen viele EU-Institutionen und die NATO","Das Atomium in Brüssel ist ein bekanntes Wahrzeichen","Westlicher Nachbar Deutschlands mit Brüssel als Hauptstadt"],"at":"11010010001"},{"a":"Dänemark","c":["Nordeuropäischer Staat auf einer Halbinsel und mit hunderten Inseln","Die berühmten Bausteine aus Plastik wurden dort erfunden","Märchenerzähler Hans Christian Andersen wurde dort geboren","Die Kleine Meerjungfrau sitzt in der Hauptstadt Kopenhagen am Hafen","Nördlicher Nachbar Deutschlands mit Kopenhagen als Hauptstadt"],"at":"11000010001"},{"a":"Finnland","c":["Nordeuropäischer Staat, der im Osten eine lange Grenze mit Russland hat","Tausende Seen und Wälder prägen die Landschaft","Die Sauna ist ein Nationalsymbol, fast jeder Haushalt hat eine","Handyhersteller Nokia stammt von dort","In Rovaniemi in Lappland liegt das Dorf des Weihnachtsmanns; Hauptstadt ist Helsinki"],"alt":["suomi"],"at":"11000000000"},{"a":"Luxemburg","c":["Einer der kleinsten Staaten Europas, ein Großherzogtum","Liegt zwischen Frankreich, Belgien und Deutschland","Hat drei Amtssprachen, darunter Deutsch und Französisch","Wichtiger Bankenplatz und Sitz von EU-Institutionen wie dem Gerichtshof","Die Hauptstadt trägt denselben Namen wie der Staat"],"at":"10010010001"},{"a":"Indien","c":["Auf der Karte hat dieser Subkontinent die Form eines Dreiecks, das in den Ozean ragt","Hier entstand das Schachspiel, und Kühe gelten vielen als heilig","Curry, Chai und bunte Feste wie Holi prägen die Kultur","Der Taj Mahal in Agra ist ein Mausoleum aus weißem Marmor","Bollywood, der Ganges und die Hauptstadt Neu-Delhi gehören dazu"],"at":"01001101100"},{"a":"Vietnam","c":["Langgestreckter Küstenstaat in Südostasien mit S-förmigem Umriss","Kegelhüte und unzählige Mopeds prägen das Straßenbild","Nudelsuppe Pho und Frühlingsrollen sind beliebte Gerichte","In der Halong-Bucht ragen tausende Kalksteininseln aus dem Meer","Hauptstadt ist Hanoi, größte Stadt ist Ho-Chi-Minh-Stadt"],"alt":["viet nam"],"at":"01000101000"},{"a":"Saudi-Arabien","c":["Der Großteil besteht aus Wüste, in der es kaum Flüsse gibt","Liegt auf der größten Halbinsel der Erde","Hier liegen Mekka und Medina, die heiligsten Städte des Islam","Riesige Ölvorkommen machen den Staat reich; Hauptstadt ist Riad","Auf der Flagge stehen das Glaubensbekenntnis und ein Schwert"],"alt":["saudiarabien","saudi arabien"],"at":"01001111000"},{"a":"Mongolei","c":["Binnenstaat in Zentralasien zwischen zwei riesigen Nachbarn","Endlose Steppe und sehr wenige Menschen pro Quadratkilometer","Nomaden leben dort in runden Zelten, den Jurten","Die Wüste Gobi erstreckt sich im Süden","Hauptstadt ist Ulaanbaatar; Dschingis Khan gründete hier ein Weltreich"],"at":"00001100100"},{"a":"Philippinen","c":["Inselstaat in Südostasien mit mehr als 7000 Inseln","Liegt im westlichen Pazifik und wird oft von Taifunen heimgesucht","Bekannt für Strände und die Reisterrassen von Banaue","Die Hauptstadt ist Manila; hier starb der Seefahrer Magellan","Benannt nach einem spanischen König des 16. Jahrhunderts"],"at":"01100101000"},{"a":"Marokko","c":["Liegt im Nordwesten Afrikas mit Küsten am Atlantik und am Mittelmeer","Nur wenige Kilometer von Europa entfernt, getrennt durch die Straße von Gibraltar","Basare, Minztee und Tajine prägen die Kultur","Marrakesch und Casablanca sind bekannte Städte, Hauptstadt ist Rabat","Das Atlasgebirge durchzieht es, im Süden beginnt die Sahara"],"at":"01001011100"},{"a":"Botswana","c":["Binnenstaat im südlichen Afrika, in dem die Kalahari liegt","Das Okavango-Delta versickert im Landesinneren","In den Nationalparks leben viele Elefanten, Löwen und Giraffen","Diamanten sind der wichtigste Exportartikel","Hauptstadt ist Gaborone; Nachbarn sind Südafrika und Namibia"],"at":"00001001010"},{"a":"Madagaskar","c":["Inselstaat im Indischen Ozean vor der Ostküste Afrikas","Gehört zu den größten Inseln der Erde","Hier leben viele Tiere, die es sonst nirgends gibt, etwa Lemuren","Baobab-Bäume säumen eine berühmte Allee","Hauptstadt ist Antananarivo; Vanille ist ein wichtiges Exportgut"],"at":"01101001010"},{"a":"Tansania","c":["Liegt in Ostafrika am Indischen Ozean","Hier steht der höchste Berg des Kontinents, der Kilimandscharo","In der Serengeti ziehen jedes Jahr Millionen Gnus","Sansibar, eine Gewürzinsel, gehört zum Staat","Größte Stadt ist Daressalam, Hauptstadt ist Dodoma"],"at":"01001001110"},{"a":"Nigeria","c":["Liegt in Westafrika am Golf von Guinea","Dort leben viele Volksgruppen, darunter Yoruba, Igbo und Hausa","Die Filmindustrie Nollywood ist hier zuhause","Wichtiger Erdölförderer","Größte Stadt ist Lagos, Hauptstadt ist Abuja"],"at":"01001001000"},{"a":"Brasilien","c":["Größter Staat Südamerikas","Hier fließt der größte Teil des Amazonas durch den Regenwald","Einziges Land Südamerikas mit Portugiesisch als Amtssprache","Karneval in Rio, Samba und Fußballlegende Pelé sind weltbekannt","Die Christusstatue auf dem Corcovado und der Zuckerhut sind Wahrzeichen"],"at":"01001001010"},{"a":"Argentinien","c":["Liegt im Süden Südamerikas und reicht bis nach Feuerland","Hier wird Tango getanzt, und Asado ist ein Nationalgericht","Fußballstars wie Maradona und Messi stammen von dort","Der Aconcagua ist der höchste Berg außerhalb Asiens","Hauptstadt ist Buenos Aires, weite Pampa und Gauchos prägen das Bild"],"at":"01001000110"},{"a":"Kanada","c":["Zweitgrößter Staat der Erde nach Fläche","Ahornblatt auf der Flagge und Ahornsirup als Spezialität","Eishockey ist ein Nationalsport","Die Niagarafälle teilt es sich mit dem südlichen Nachbarn","Hauptstadt ist Ottawa; Amtssprachen sind Englisch und Französisch"],"at":"01001010100"},{"a":"Mexiko","c":["Liegt südlich der USA zwischen Pazifik und Karibik","Hier bauten Maya und Azteken große Pyramiden","Tacos, Tequila und scharfe Chilis","Am Tag der Toten feiert man mit bunten Totenköpfen","Die Hauptstadt liegt auf den Ruinen der Aztekenstadt Tenochtitlán"],"at":"01001001100"},{"a":"Kuba","c":["Größte Insel der Karibik","Oldtimer aus den 1950er Jahren prägen das Straßenbild","Zigarren und Rum sind wichtige Exportgüter","Hauptstadt ist Havanna; Salsa und Son sind typische Musikstile","Che Guevara und Fidel Castro machten die Revolution von 1959 berühmt"],"at":"01100001000"},{"a":"Vereinigte Staaten","c":["Größte Volkswirtschaft der Erde, bestehend aus 50 Bundesstaaten","Hollywood, Silicon Valley und die Wall Street sind hier zuhause","Freiheitsstatue und Grand Canyon sind Wahrzeichen","Die Flagge heißt Stars and Stripes","Hauptstadt ist Washington, D.C."],"alt":["usa","vereinigte staaten von amerika","us"],"at":"01001000100"},{"a":"Australien","c":["Liegt auf der Südhalbkugel und ist zugleich Staat und Kontinent","Känguru, Koala und Schnabeltier leben dort","Das Great Barrier Reef ist das größte Korallenriff der Erde","Opernhaus in Sydney und Uluru sind Wahrzeichen","Hauptstadt ist Canberra, nicht Sydney oder Melbourne"],"at":"01001011010"},{"a":"Neuseeland","c":["Zwei große Inseln im Südwestpazifik, getrennt vom Nachbarn durch die Tasmansee","Hier wurde die Verfilmung von „Der Herr der Ringe“ gedreht","Der Kiwi ist Nationalvogel, die Maori sind die Ureinwohner","Schafe sind sehr zahlreich; Hauptstadt ist Wellington","Kleinerer Nachbar von Australien auf der anderen Seite der Tasmansee"],"alt":["neu seeland"],"at":"01100010010"},{"a":"Fidschi","c":["Inselstaat im Südpazifik mit über dreihundert Inseln","Tropisches Urlaubsziel mit Palmenstränden und Korallenriffen","Kava ist das traditionelle Getränk","Hauptstadt ist Suva auf der Insel Viti Levu","Liegt nahe bei Tonga und Vanuatu"],"alt":["fiji"],"at":"01100001010"}]},{"id":"personen","name":"Persönlichkeiten","icon":"⭐","qs":[{"k":"frau","t":"Ist es eine Frau?"},{"k":"musik","t":"War die Person Musiker/in oder Komponist/in?"},{"k":"wissen","t":"War die Person Wissenschaftler/in?"},{"k":"deutsch","t":"Wurde die Person in Deutschland geboren?"},{"k":"sport","t":"War die Person Sportler/in?"},{"k":"kunst","t":"War die Person Maler/in, Dichter/in oder Schauspieler/in?"},{"k":"frueh","t":"Wurde die Person vor 1850 geboren?"},{"k":"politik","t":"War die Person Politiker/in oder Herrscher/in?"},{"k":"nobel","t":"Hat die Person einen Nobelpreis erhalten?"},{"k":"erfinder","t":"Ist die Person vor allem für Erfindungen oder Entdeckungen bekannt?"},{"k":"usa","t":"Hat die Person überwiegend in den USA gelebt?"}],"items":[{"a":"Albert Einstein","c":["Wurde 1879 in Ulm geboren","Arbeitete zeitweise als Beamter im Patentamt in Bern","Erhielt den Nobelpreis für Physik für die Erklärung des photoelektrischen Effekts","Musste 1933 emigrieren und starb 1955 in Princeton","Physiker mit wilder Frisur, Schöpfer der Relativitätstheorie und der Formel E = mc²"],"alt":["einstein"],"at":"00110000100"},{"a":"Ludwig van Beethoven","c":["Wurde 1770 in Bonn geboren","Schrieb sein berühmtes Heiligenstädter Testament wegen zunehmender Schwerhörigkeit","Komponierte die Oper Fidelio und die Mondscheinsonate","Wurde im Laufe seines Lebens taub und starb 1827 in Wien","Komponierte neun Sinfonien, die letzte mit der Ode an die Freude"],"alt":["beethoven"],"at":"01010010000"},{"a":"Marie Curie","c":["Wurde 1867 in Warschau geboren","Studierte und forschte in Paris an der Sorbonne","Entdeckte 1898 gemeinsam mit ihrem Mann die Elemente Polonium und Radium","Prägte den Begriff Radioaktivität und starb 1934 an den Folgen der Strahlung","Erhielt als erste Person zwei Nobelpreise: Physik 1903 und Chemie 1911"],"alt":["curie"],"at":"10100000110"},{"a":"Leonardo da Vinci","c":["Wurde 1452 in einem Dorf bei Florenz geboren","Entwarf Flugmaschinen, Kanonen und Brücken, die oft nie gebaut wurden","Zeichnete den vitruvianischen Menschen und schrieb in Spiegelschrift","Malte das Abendmahl in Mailand und starb 1519 in Frankreich","Italienisches Universalgenie, malte die Dame mit dem rätselhaften Lächeln im Louvre"],"alt":["leonardo","da vinci"],"at":"00000110010"},{"a":"Johann Wolfgang von Goethe","c":["Wurde 1749 in Frankfurt am Main geboren","Wirkte jahrzehntelang als Minister am Hof in Weimar","Schrieb den Briefroman Die Leiden des jungen Werthers","Starb 1832 in Weimar, gilt als bedeutendster deutscher Dichter","Verfasste das Drama über einen Gelehrten, der einen Pakt mit Mephisto schließt"],"alt":["goethe"],"at":"00010110000"},{"a":"Muhammad Ali","c":["Wurde 1942 in Louisville im US-Bundesstaat Kentucky geboren","Gewann 1960 bei den Olympischen Spielen in Rom Gold im Halbschwergewicht","Änderte 1964 seinen Namen nach dem Beitritt zur Nation of Islam","Besiegte 1974 in Kinshasa den Boxer George Foreman, erkrankte später an Parkinson","Boxer: Schwebe wie ein Schmetterling, steche wie eine Biene"],"alt":["ali"],"at":"00001000001"},{"a":"Wolfgang Amadeus Mozart","c":["Wurde 1756 in Salzburg geboren","Reiste als Kind mit seiner Schwester durch die Höfe Europas","Komponierte Don Giovanni und Die Hochzeit des Figaro","Starb 1791 in Wien, sein Requiem blieb unvollendet","Wunderkind-Komponist, schrieb Die Zauberflöte und Eine kleine Nachtmusik"],"alt":["mozart"],"at":"01000010000"},{"a":"Michael Jackson","c":["Wurde 1958 in Gary im Bundesstaat Indiana geboren","Begann als Kinderstar in einer Familienband","Sein Album Thriller (1982) gilt als meistverkauftes Album aller Zeiten","Starb 2009 in Los Angeles","Sänger mit Handschuh und Moonwalk, genannt King of Pop"],"alt":["jackson"],"at":"01000000001"},{"a":"Frida Kahlo","c":["Wurde 1907 in Coyoacán bei Mexiko-Stadt geboren","Überlebte als Jugendliche einen schweren Busunfall","War mit dem Wandmaler Diego Rivera verheiratet","Starb 1954 in ihrem Elternhaus, der Casa Azul","Mexikanische Malerin, bekannt für Selbstbildnisse mit durchgehender Augenbraue"],"alt":["kahlo","frida"],"at":"10000100000"},{"a":"Napoleon Bonaparte","c":["Wurde 1769 auf der Insel Korsika geboren","Stieg im Heer der Französischen Revolution zum General auf","Krönte sich 1804 selbst zum Kaiser der Franzosen","Unterlag 1815 bei Waterloo und starb 1821 in der Verbannung auf St. Helena","Französischer Feldherr und Kaiser, dem Klischee nach klein und mit Hand in der Weste"],"alt":["napoleon"],"at":"00000011000"},{"a":"Pelé","c":["Wurde 1940 in Brasilien geboren","Spielte lange für den FC Santos","Wurde 1958, 1962 und 1970 Weltmeister","Starb 2022 in São Paulo","Brasilianischer Fußballer mit der Rückennummer 10, genannt König des Fußballs"],"alt":["pele","pelé"],"at":"00001000000"},{"a":"Marilyn Monroe","c":["Wurde 1926 in Los Angeles geboren","Spielte 1959 in der Komödie Manche mögen's heiß","Berühmte Szene: Ein weißes Kleid wird von einem U-Bahn-Schacht aufgewirbelt","Sang 1962 Happy Birthday, Mr. President und starb im selben Jahr","Blonde Hollywood-Schauspielerin, Sexsymbol der 1950er Jahre"],"alt":["monroe","marilyn"],"at":"10000100001"},{"a":"Roald Amundsen","c":["Wurde 1872 in Norwegen geboren","Durchquerte als Erster mit einem Schiff die Nordwestpassage (1903 bis 1906)","Lieferte sich einen Wettlauf mit dem Briten Robert Falcon Scott","Erreichte am 14. Dezember 1911 als Erster den Südpol","Norwegischer Polarforscher, verschollen 1928 bei einem Rettungsflug in der Arktis"],"alt":["amundsen"],"at":"00000000010"},{"a":"Johannes Gutenberg","c":["Wurde um das Jahr 1400 in Mainz geboren","Arbeitete als Goldschmied und Unternehmer","Entwickelte bewegliche Metalllettern und eine Druckerpresse","Druckte um 1452 bis 1455 die 42-zeilige Bibel","Erfinder des modernen Buchdrucks in Europa, starb 1468 in Mainz"],"alt":["gutenberg"],"at":"00010010010"},{"a":"Johann Sebastian Bach","c":["Wurde 1685 in Eisenach geboren","War ab 1723 Thomaskantor in Leipzig","Komponierte die Matthäus-Passion und die Brandenburgischen Konzerte","Hatte zwanzig Kinder, von denen mehrere ebenfalls Komponisten wurden","Barockkomponist und Orgelvirtuose, schrieb die Toccata und Fuge in d-Moll"],"alt":["bach"],"at":"01010010000"},{"a":"Vincent van Gogh","c":["Wurde 1853 in Zundert in den Niederlanden geboren","Verkaufte zu Lebzeiten kaum ein Bild","Malte 1888 in Arles und schnitt sich dort einen Teil des Ohrs ab","Starb 1890 in Auvers-sur-Oise nach einem Schuss","Niederländischer Maler von Sonnenblumen und der Sternennacht"],"alt":["van gogh","gogh"],"at":"00000100000"},{"a":"Pablo Picasso","c":["Wurde 1881 in Málaga in Spanien geboren","Durchlief eine blaue und eine rosa Periode","Entwickelte gemeinsam mit Georges Braque den Kubismus","Malte 1937 das Antikriegsbild Guernica","Spanischer Maler und Bildhauer, starb 1973 in Frankreich"],"alt":["picasso"],"at":"00000100000"},{"a":"Mahatma Gandhi","c":["Wurde 1869 in Porbandar in Indien geboren","Arbeitete zunächst als Rechtsanwalt in Südafrika","Führte 1930 den Salzmarsch an","Setzte auf gewaltlosen Widerstand gegen die britische Kolonialherrschaft","Wurde 1948 in Neu-Delhi ermordet, Wegbereiter der Unabhängigkeit Indiens"],"alt":["gandhi"],"at":"00000011000"},{"a":"Abraham Lincoln","c":["Wurde 1809 in einer Blockhütte in Kentucky geboren","Arbeitete als Rechtsanwalt in Illinois","Hielt 1863 eine kurze Rede auf dem Schlachtfeld von Gettysburg","Führte die Nordstaaten im Sezessionskrieg und trat gegen die Sklaverei ein","Der 16. Präsident der USA, 1865 im Ford's Theatre erschossen"],"alt":["lincoln"],"at":"00000011001"},{"a":"Königin Victoria","c":["Wurde 1819 in London geboren","Bestieg 1837 mit 18 Jahren den Thron","Ihr Ehemann war Prinz Albert, mit dem sie neun Kinder hatte","Wurde 1876 zur Kaiserin von Indien ernannt","Britische Monarchin mit 63 Regierungsjahren, starb 1901 auf der Isle of Wight"],"alt":["victoria"],"at":"10000011000"},{"a":"Mutter Teresa","c":["Wurde 1910 in Skopje geboren","Ging 1929 als Ordensschwester nach Indien","Gründete 1950 in Kalkutta die Missionarinnen der Nächstenliebe","Erhielt 1979 den Friedensnobelpreis","Katholische Ordensfrau, die Arme und Sterbende pflegte, 2016 heiliggesprochen"],"alt":["teresa","mutter teresa"],"at":"10000000100"},{"a":"Maria Callas","c":["Wurde 1923 in New York als Kind griechischer Eltern geboren","Galt als eine der größten Sopranistinnen des 20. Jahrhunderts","Sang berühmte Partien wie Norma und Tosca","Hatte eine Liebesbeziehung mit dem Reeder Aristoteles Onassis","Opernsängerin, genannt La Divina, starb 1977 in Paris"],"alt":["callas"],"at":"11000000000"},{"a":"Rosa Parks","c":["Wurde 1913 in Tuskegee im Bundesstaat Alabama geboren","Arbeitete als Näherin und engagierte sich in der Bürgerrechtsorganisation NAACP","Weigerte sich 1955 in Montgomery, ihren Sitzplatz in einem Bus zu räumen","Ihre Verhaftung löste einen großen Busboykott aus","Wird als Mutter der Bürgerrechtsbewegung der USA bezeichnet, starb 2005 in Detroit"],"alt":["parks"],"at":"10000000001"},{"a":"Martin Luther King","c":["Wurde 1929 in Atlanta im Bundesstaat Georgia geboren","Arbeitete als Baptistenpastor","Hielt 1963 beim Marsch auf Washington die Rede I have a dream","Erhielt 1964 den Friedensnobelpreis","Führer der US-Bürgerrechtsbewegung, 1968 in Memphis erschossen"],"alt":["king","luther king"],"at":"00000000101"},{"a":"Nelson Mandela","c":["Wurde 1918 in Südafrika geboren","Arbeitete als Rechtsanwalt und kämpfte gegen die Apartheid","Saß von 1962 bis 1990 27 Jahre im Gefängnis, lange auf Robben Island","Erhielt 1993 gemeinsam mit F. W. de Klerk den Friedensnobelpreis","Wurde 1994 der erste schwarze Präsident Südafrikas, starb 2013"],"alt":["mandela"],"at":"00000001100"},{"a":"William Shakespeare","c":["Wurde 1564 in Stratford-upon-Avon in England geboren","Wirkte als Schauspieler und Mitbesitzer am Londoner Globe Theatre","Schrieb Tragödien wie Hamlet und Macbeth","Schrieb auch das Liebesdrama über zwei Kinder verfeindeter Familien in Verona","Englischer Dramatiker, starb 1616, Zitat: Sein oder nicht sein"],"alt":["shakespeare"],"at":"00000110000"},{"a":"Jimi Hendrix","c":["Wurde 1942 in Seattle geboren","Spielte als Linkshänder eine umgedrehte Rechtshändergitarre","Verbrannte 1967 in Monterey auf der Bühne seine Gitarre","Spielte 1969 in Woodstock die US-Nationalhymne mit verzerrter E-Gitarre","Gitarrenlegende, starb 1970 mit 27 Jahren in London"],"alt":["hendrix","jimi"],"at":"01000000001"},{"a":"Stephen Hawking","c":["Wurde 1942 in Oxford geboren","Wurde mit 21 Jahren mit der Nervenkrankheit ALS diagnostiziert","Hatte den Lucasischen Lehrstuhl in Cambridge inne","Schrieb 1988 das Bestseller-Sachbuch Eine kurze Geschichte der Zeit","Britischer Astrophysiker im Rollstuhl, sprach mit Sprachcomputer, starb 2018"],"alt":["hawking"],"at":"00100000000"},{"a":"Thomas Mann","c":["Wurde 1875 in Lübeck geboren","Schrieb 1901 den Familienroman Buddenbrooks","Verfasste die Romane Der Zauberberg und Doktor Faustus","Erhielt 1929 den Nobelpreis für Literatur","Deutscher Schriftsteller, 1933 ins Exil gegangen, starb 1955 in Zürich"],"alt":["mann"],"at":"00010100100"},{"a":"Jesse Owens","c":["Wurde 1913 in Alabama geboren","Stellte 1935 an einem einzigen Nachmittag mehrere Weltrekorde auf","Gewann 1936 bei den Olympischen Spielen in Berlin vier Goldmedaillen","Siegte unter anderem im 100-Meter-Lauf und im Weitsprung","US-Sprinter, der Hitlers Rassenideologie bei der Olympiade widerlegte, starb 1980"],"alt":["owens"],"at":"00001000001"}]},{"id":"gegenstaende","name":"Gegenstände","icon":"📦","qs":[{"k":"strom","t":"Braucht es Strom (Netz oder Batterie)?"},{"k":"tasche","t":"Passt es in eine Hosentasche?"},{"k":"kueche","t":"Findet man es typischerweise in der Küche?"},{"k":"raeder","t":"Hat es Räder?"},{"k":"metall","t":"Besteht es überwiegend aus Metall?"},{"k":"musik","t":"Hat es mit Musik zu tun?"},{"k":"taeglich","t":"Benutzen die meisten Menschen es fast täglich?"},{"k":"teuer","t":"Kostet es neu meist mehr als 100 €?"},{"k":"display","t":"Hat es einen Bildschirm?"},{"k":"draussen","t":"Benutzt man es meist draußen?"},{"k":"schreiben","t":"Schreibt oder zeichnet man damit?"},{"k":"glas","t":"Besteht es (teilweise) aus Glas?"}],"items":[{"a":"Fahrrad","c":["Man treibt es allein mit Muskelkraft an","Es hat zwei runde Laufflächen, aber keinen Motor","Man hält sich an einer Lenkstange fest und balanciert","Man sitzt auf einem Sattel und tritt in die Pedale","Hat Kette, Klingel, Lenker und Sattel"],"alt":["rad","drahtesel"],"at":"000110010100"},{"a":"Kühlschrank","c":["Es läuft meist rund um die Uhr","Es hält Lebensmittel länger frisch","Innen ist es kalt, oft brennt dort beim Öffnen ein Licht","Darin lagern Milch, Butter und Joghurt","Das Gerät mit Gefrierfach in der Küche"],"alt":["kuehlschrank","kühlschrank"],"at":"101010110001"},{"a":"Regenschirm","c":["Man trägt es meist nur bei bestimmtem Wetter bei sich","Es lässt sich zusammenschieben und aufspannen","Es hat einen Griff und mehrere dünne Streben","Es hält Wasser von oben ab","Tragbares Dach aus Stoff, das bei Niederschlag aufgespannt wird"],"alt":["schirm","knirps"],"at":"000010000100"},{"a":"Smartphone","c":["Viele Menschen schauen es dutzende Male am Tag an","Man trägt es fast überall bei sich","Es hat Kamera, Lautsprecher und Mikrofon","Man bedient es mit Fingerwischen auf dem Bildschirm","Tragbares Telefon mit Apps und Touchscreen"],"alt":["handy","mobiltelefon"],"at":"110000111001"},{"a":"Brille","c":["Manche Menschen können ohne es nicht gut zurechtkommen","Es sitzt im Gesicht und liegt auf der Nase","Es hat zwei Bügel, die hinter den Ohren aufliegen","Es korrigiert eine Fehlsichtigkeit","Gläser in einem Gestell, damit man scharf sieht"],"alt":["sehhilfe"],"at":"000000010001"},{"a":"Gitarre","c":["Es gibt sie in vielen Größen und Stilrichtungen","Man hält es meist im Sitzen auf dem Schoß oder am Gurt","Es hat einen Hals mit Bünden","Man zupft oder schlägt Saiten an","Saiteninstrument mit Schallloch und sechs Saiten"],"alt":["akustikgitarre","klampfe"],"at":"000001000000"},{"a":"Taschenlampe","c":["Man greift danach, wenn es dunkel ist","Es ist handlich und wird meist in der Hand gehalten","Es braucht eine Energiequelle, die man austauschen kann","Es hat einen Schalter und einen gebündelten Lichtstrahl","Mobile Lichtquelle mit Batterien zum Leuchten im Dunkeln"],"alt":["lampe"],"at":"110010000100"},{"a":"Waschmaschine","c":["Es steht in vielen Haushalten und läuft nur zeitweise","Es braucht einen Wasseranschluss und Strom","Man öffnet eine runde Klappe und füllt es von vorn","Im Inneren dreht sich eine Trommel","Reinigt schmutzige Kleidung mit Wasser und Seifenlauge"],"alt":["waschautomat"],"at":"100010011001"},{"a":"Fernglas","c":["Man benutzt es vor allem in der Freizeit","Es besteht aus zwei gleichen Röhren, die verbunden sind","Man hält es sich vor die Augen","Es hat Linsen und ein Rädchen zum Scharfstellen","Optisches Gerät, das Weitentlegenes näher heranholt"],"alt":["feldstecher","binokular"],"at":"000000000101"},{"a":"Staubsauger","c":["Man benutzt es gelegentlich zu Hause","Es ist laut und braucht eine Energiequelle","Es erzeugt einen Luftstrom, der etwas einsaugt","Es hat Schlauch, Rohr und Düse","Gerät zum Saugen von Krümeln und Schmutz vom Teppich"],"alt":["sauger"],"at":"100100010000"},{"a":"Kugelschreiber","c":["Er ist klein, billig und sehr verbreitet","Man hat ihn oft in einer Jacke oder auf dem Schreibtisch","Er enthält eine dünne Mine mit Farbe","Er hat eine winzige rollende Metallspitze","Stift mit Tintenmine, den man klickt oder abschraubt"],"alt":["kuli","kugelschreiber"],"at":"010000000010"},{"a":"Glühbirne","c":["Sie ist klein und hat eine bekannte Form","Man schraubt sie in eine Fassung","Sie besteht zum Teil aus dünnem Material und geht leicht kaputt","Ein Draht in ihrem Inneren erhitzt sich","Sie leuchtet in der Deckenlampe, wenn man den Schalter drückt"],"alt":["gluehbirne","birne","glühlampe"],"at":"110000100001"},{"a":"Toaster","c":["Das Gerät wird vor allem morgens benutzt","Es hat Heizdrähte und einen Hebel zum Absenken","Es hat Schlitze, in die etwas Flaches gesteckt wird","Es bräunt Scheiben in wenigen Minuten","Hier wird Brot knusprig gebräunt"],"at":"101010000000"},{"a":"Bügeleisen","c":["Es wird heiß und hat eine glatte Unterseite","Man schiebt es über Textilien","Es hat einen Griff, einen Temperaturregler und oft Dampf","Es beseitigt Falten","Damit glättet man Hemden auf einem Brett"],"alt":["bügeleisen","buegeleisen"],"at":"100010000000"},{"a":"Klavier","c":["Es ist sehr groß, schwer und teuer","Es hat Hunderte bewegliche Teile im Inneren","Es hat schwarze und weiße Tasten","Man schlägt Tasten an, wodurch Hämmer Saiten treffen","Tasteninstrument, auf dem man in die Tasten greift"],"alt":["piano"],"at":"000001010000"},{"a":"Dosenöffner","c":["Es liegt meist in einer Schublade","Es ist klein und hat oft einen Drehgriff","Es hat eine scharfe Klinge oder ein Schneidrad","Man benötigt es für Konserven","Damit öffnet man Konservendeckel aus Blech"],"alt":["dosenoeffner"],"at":"001010000000"},{"a":"Einkaufswagen","c":["Man findet es in Gebäuden, in denen man etwas kaufen kann","Viele schieben es durch lange Gänge","Es hat meist vier Räder und einen Schiebegriff","Es besteht aus Gitterstäben, oft mit Münzpfand","Ein Gitterkorb auf Rädern im Supermarkt"],"alt":["einkaufswagen","wagen"],"at":"000110000000"},{"a":"Mikrowelle","c":["Es wird in vielen Haushalten benutzt, aber selten für große Mahlzeiten","Es hat eine Tür mit Fenster und eine Zeitwahl","Der Teller dreht sich darin","Es wärmt Essen in kurzer Zeit auf","Gerät, das Speisen mit Strahlung erhitzt und piept"],"alt":["mikrowellenherd","mikrowellenofen"],"at":"101010001001"},{"a":"Mundharmonika","c":["Es ist ein handliches Instrument","Man führt es an die Lippen und bewegt es hin und her","Es hat viele kleine Kammern in einer Reihe","Man bläst und saugt durch Löcher","Musikinstrument mit Metallzungen, das man an die Lippen setzt"],"alt":["mundorgel","harmonika"],"at":"010011000000"},{"a":"Trompete","c":["Dieses Instrument ist laut und hell im Klang","Es besteht aus einem langen gebogenen Rohr","Es hat drei Ventile","Man bläst durch ein Mundstück","Blechblasinstrument, auf dem man Fanfaren spielt"],"at":"000011010000"},{"a":"Laptop","c":["Es ist tragbar, aber nicht so klein wie eine Hosentasche","Man klappt es auf und zu","Man tippt auf einer Tastatur","Es hat einen Akku und einen aufklappbaren Bildschirm","Tragbarer Computer"],"alt":["notebook"],"at":"100000111001"},{"a":"Fernseher","c":["Es steht oder hängt meist in einem Wohnzimmer","Es wird in vielen Haushalten täglich benutzt","Man bedient es per Knopfdruck vom Sofa aus","Es zeigt bewegte Bilder und Ton","Gerät für Filme, Nachrichten und Serien"],"alt":["tv","glotze","fernsehgerät"],"at":"100000111001"},{"a":"Schubkarre","c":["Man nutzt es vor allem bei körperlicher Arbeit","Es hat zwei Griffe und ein Gestell","Man schiebt es und hebt dabei die Griffe an","Es transportiert Erde, Sand oder Steine","Einrädriger Transportwagen im Garten oder auf der Baustelle"],"alt":["schubkarren","karre"],"at":"000110000100"},{"a":"Bleistift","c":["Es ist ein einfaches Werkzeug, oft aus Holz","Man benutzt es in Schule und Büro","Seine Spitze nutzt sich ab und wird mit einem Gerät erneuert","Damit schreibt man, und man kann es wegradieren","Holzstab mit grauer Mine aus Graphit"],"at":"010000000010"},{"a":"Schlüssel","c":["Er ist klein, meist aus Metall und hat Zacken","Viele tragen ihn täglich bei sich","Man hängt ihn gern an einen Ring","Er passt in ein Schloss","Damit schließt man Türen auf und zu"],"alt":["schluessel"],"at":"010010100000"},{"a":"Fön","c":["Man benutzt es im Bad, meist nach dem Waschen","Es wird warm und ist laut","Es bläst heiße Luft","Es hat einen Griff und eine Düse vorn","Damit trocknet man nasse Haare"],"alt":["foen","haartrockner"],"at":"100000000000"},{"a":"Taschenrechner","c":["Er ist klein und flach","Man findet ihn oft in Schulranzen","Er hat viele Tasten mit Ziffern und Symbolen","Er hat eine kleine Anzeige für Zahlen","Gerät zum Addieren, Subtrahieren und Multiplizieren"],"alt":["rechner"],"at":"110000001000"},{"a":"Pfanne","c":["Es steht oft auf dem Herd","Es ist flach, rund und hat einen langen Stiel","Es wird heiß, oft mit Fett oder Öl","Man wendet darin Speisen","Küchengerät zum Braten von Spiegelei und Schnitzel"],"alt":["bratpfanne"],"at":"001010000000"},{"a":"Mikroskop","c":["Man findet es vor allem in Schule, Labor oder Praxis","Man stellt es mit Rädchen scharf","Es hat mehrere Linsen und einen Objekttisch","Man blickt hinein, um ganz Kleines zu sehen","Gerät zum Betrachten von Zellen und Bakterien"],"at":"000010010001"},{"a":"Schere","c":["Es ist ein verbreitetes Werkzeug mit zwei Teilen","Es hat zwei Öffnungen für die Finger","Zwei Klingen sind in der Mitte verbunden","Man öffnet und schließt sie, um etwas zu trennen","Damit schneidet man Papier, Stoff oder Haare"],"at":"000010000000"}]},{"id":"radio","name":"Radio & Musik","icon":"🎙️","qs":[],"items":[{"a":"Gitarre","c":["Wird gezupft oder angeschlagen","Hat meist sechs Saiten und einen langen Hals mit Bünden","Der Korpus hat oft ein rundes Schallloch","Typisch am Lagerfeuer und in Rockbands","Saiteninstrument, das es als akustische und elektrische Variante gibt"]},{"a":"Schlagzeug","c":["Mehrere Instrumente, die eine Person gleichzeitig bedient","Gespielt mit Stöcken und mit den Füßen","Besteht aus Trommeln und Becken, dazu gehört die Hi-Hat","Gibt in einer Band den Takt vor","Im Englischen heißt es Drums"],"alt":["drums","drumset"]},{"a":"Mikrofon","c":["Wandelt eine physikalische Größe in ein elektrisches Signal um","Wird bei Konzerten, Interviews und Aufnahmen gebraucht","Gibt es mit Kabel oder drahtlos, oft in der Hand gehalten","Sänger und Sprecher richten sich direkt daran","Wandelt Schall in Strom um und macht Stimmen lauter"],"alt":["mikro","mikrophon"]},{"a":"Kopfhörer","c":["Liegt auf oder über den Ohren","Wird per Kabel oder Bluetooth mit einem Abspielgerät verbunden","Zwei kleine Lautsprecher, durch einen Bügel verbunden","Damit genießt man Musik, ohne dass andere etwas mitbekommen","Englisch: Headphones"],"alt":["headphones","kopfhoerer"]},{"a":"UKW","c":["Abkürzung aus der Funktechnik","Frequenzbereich etwa von 87,5 bis 108 MHz","Bietet im Radio guten Klang mit wenig Rauschen","Konkurrenz zu DAB+ und Mittelwelle","Radio-Standard, im Englischen als FM bekannt"],"alt":["ultrakurzwelle","fm"]},{"a":"Podcast","c":["Wird nicht live gesendet, sondern bei Bedarf abgerufen","Erscheint meist in Folgen, die man abonnieren kann","Beliebt bei Pendlern, Joggern und beim Putzen","Gesprächs- oder Erzählformat zum Anhören im Netz","Radiosendung auf Abruf aus dem Internet, Folge für Folge"],"alt":["podcasts"]},{"a":"Jingle","c":["Sehr kurz, meist nur wenige Sekunden","Wird zwischen Beiträgen im Radio eingespielt","Soll einen Sender oder eine Marke wiedererkennbar machen","Eingängige Tonfolge, oft mit gesprochenem oder gesungenem Sendernamen","Kurzes Erkennungsmotiv für Sender und Werbung"],"alt":["radiojingle"]},{"a":"Mischpult","c":["Steht im Studio und bei Konzerten oft hinter dem Publikum","Viele Regler und Knöpfe in Reihen angeordnet","Vereint mehrere Tonquellen zu einem Signal","Damit stellen Tontechniker Lautstärke und Klang jedes Kanals ein","Englisch: Mixing Desk"],"alt":["mixer","mischer"]},{"a":"Reggae","c":["Entstand in den 1960ern auf einer Karibikinsel","Entspannter Rhythmus mit Betonung auf den Zählzeiten zwei und vier","Rot, Gelb und Grün gehören zu seinem Erscheinungsbild","Bob Marley ist sein bekanntester Vertreter","Musikstil aus Jamaika"]},{"a":"Schlager","c":["Meist deutschsprachig, eingängig und gefühlvoll","Die Texte handeln oft von Liebe, Sehnsucht und Urlaub","Läuft häufig in Samstagabend-Shows im Fernsehen","Helene Fischer und Roland Kaiser sind bekannte Namen","Musikrichtung mit einfachen Melodien und Mitsing-Refrains"]},{"a":"Geige","c":["Hat vier Saiten, die in Quinten gestimmt sind","Wird mit einem Bogen aus Rosshaar gestrichen","Wird beim Musizieren unters Kinn geklemmt","Das kleinste und höchste Streichinstrument im Orchester","Klassisches Streichinstrument, auch Violine genannt"],"alt":["violine"]},{"a":"Saxofon","c":["Gebogenes Instrument aus Metall mit Mundstück und Klappen","Klingt warm und rauchig, oft im Jazz zu hören","Der Ton entsteht durch ein Rohrblatt","Zählt zu den Holzblasinstrumenten, obwohl es aus Metall ist","Es gibt Sopran, Alt, Tenor und Bariton"],"alt":["saxophon"]},{"a":"Plattenspieler","c":["Gerät mit rotierendem Teller","Hat einen schwenkbaren Arm mit feiner Nadel","Läuft mit 33 oder 45 Umdrehungen pro Minute","Gibt Vinyl wieder","Gerät für Vinyl-Scheiben mit Nadel und Tonarm"],"alt":["schallplattenspieler","turntable"]},{"a":"Antenne","c":["Metallteil, oft auf dem Dach oder an einem Mast","Fängt unsichtbare Wellen auf oder sendet sie aus","Ohne sie gibt es keinen Empfang bei Radio und Fernsehen","Früher bei Autos als Stab ausfahrbar","Stab oder Draht für den Funkempfang"]},{"a":"Moderator","c":["Beruf mit viel Sprechen, oft schon früh morgens","Führt durch Sendungen und kündigt Beiträge an","Begrüßt das Publikum und plaudert zwischen den Liedern","Arbeitet im Radio im Studio und im Fernsehen vor der Kamera","Person, die durch eine Radio- oder Fernsehsendung führt"],"alt":["moderatorin","radiomoderator"]},{"a":"Charts","c":["Ändert sich in der Regel jede Woche","Wird nach Verkäufen und Streams berechnet","Platz eins ist das Ziel jeder Veröffentlichung","Gibt es als Top 10 oder Top 100","Rangfolge der erfolgreichsten Songs, auch Hitparade genannt"],"alt":["hitparade","hitliste"]},{"a":"Remix","c":["Ein bestehendes Stück wird verändert","Meist von einem anderen Künstler als dem Original","Oft für die Tanzfläche schneller oder basslastiger gemacht","Neufassung eines Songs aus den vorhandenen Tonspuren","Neu bearbeitete Version eines Liedes"],"alt":["remixen"]},{"a":"Playlist","c":["Eine persönliche Zusammenstellung","Enthält Titel in einer bestimmten Reihenfolge","Gibt es für Sport, Partys oder zum Einschlafen","Wird bei Streamingdiensten angelegt und mit Freunden geteilt","Zusammenstellung von Songs, die nacheinander abgespielt werden"],"alt":["wiedergabeliste","abspielliste"]},{"a":"Orchester","c":["Große Gruppe von Musikern","Sitzt meist auf einer Bühne in fester Anordnung","Streicher, Bläser und Pauken musizieren gemeinsam","Führt Sinfonien und Opern auf","Ensemble aus Dutzenden Instrumentalisten, z. B. die Berliner Philharmoniker"],"alt":["sinfonieorchester"]},{"a":"Dirigent","c":["Steht meist mit dem Rücken zum Publikum","Gibt Einsätze und Tempo vor, ohne selbst Töne zu erzeugen","Benutzt oft einen dünnen weißen Stab","Leitet ein Orchester oder einen Chor","Person mit Taktstock vor den Musikern"],"alt":["dirigentin"]},{"a":"Klavier","c":["Hat 88 Tasten in Schwarz und Weiß","Im Inneren treffen kleine Hämmer auf Saiten","Hat meist Pedale am Boden","Tasteninstrument, das in Wohnzimmern und Konzertsälen steht","Instrument, auf dem man Töne durch Tastendruck erzeugt, auch Piano genannt"],"alt":["piano"]},{"a":"Lautsprecher","c":["Enthält eine bewegliche Membran","Wandelt ein elektrisches Signal in Schall um","Steckt in Fernsehern, Handys und Anlagen","Gibt es als Bluetooth-Variante zum Mitnehmen","Gerät, aus dem der Ton kommt, oft als Box bezeichnet"],"alt":["box","boxen"]},{"a":"Trompete","c":["Instrument aus Messing mit Mundstück","Hat drei Ventile","Klingt hell und strahlend, oft bei Fanfaren","Miles Davis und Louis Armstrong spielten sie im Jazz","Blechblasinstrument mit drei Ventilen und glänzendem Klang"]},{"a":"Techno","c":["Elektronische Tanzmusik","Entstand in den 1980ern in Detroit","Stark wiederholte Beats, kaum Gesang","Die Berliner Loveparade war ein berühmtes Fest dafür","Clubmusik mit hartem Viervierteltakt und etwa 120 bis 150 BPM"]}]}];
